#include <iostream>
using namespace std;

int main() {
    int n = 3;
    while (n > 0) {
        cout << n << endl;
        n--;
    }
    cout << "Liftoff!" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int i = 1;
    int sum = 0;
    while (i <= 5) {
        sum += i;
        i++;
    }
    cout << "Sum: " << sum << endl;
    return 0;
}

